{
  "plan": "O programa usa checked_add em mint, portanto a hipotese de overflow aritmetico deve ser testada executando mint com amount = u64::MAX sobre um ledger cujo total_supply ja e 1. O baseline inicializa o ledger com initial_supply = 1 e depois chama mint com amount = 1, provando que o cenario esta montado corretamente. O ataque repete mint com amount = u64::MAX, que se fosse vulneravel faria total_supply dar a volta; como o codigo usa checked_add, espera-se rejeicao. O efeito medido seria total_supply menor que o valor anterior ou igual a u64::MAX, demonstrando wrap-around.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let init_ix = env.anchor_ix(
    "initialize",
    &(1u64,),
    &[
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let init_accounts = [
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];

let init_result = env.baseline("initialize ledger with supply 1", &init_ix, &init_accounts);

let ledger_after_init = after(&init_result, &ledger_key).clone();

let mint_ix = env.anchor_ix(
    "mint",
    &(1u64,),
    &[
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let mint_accounts = [
    (ledger_key, ledger_after_init.clone()),
    (authority, wallet(1_000_000_000)),
];

let baseline_result = env.baseline("mint 1 token", &mint_ix, &mint_accounts);

let ledger_after_baseline = after(&baseline_result, &ledger_key).clone();

let attack_ix = env.anchor_ix(
    "mint",
    &(u64::MAX,),
    &[
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let attack_accounts = [
    (ledger_key, ledger_after_baseline.clone()),
    (authority, wallet(1_000_000_000)),
];

let attack_result = env.attack("mint u64::MAX to overflow total_supply", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let data = after(&attack_result, &ledger_key).data();
    let total_supply = read_u64(data, 40);
    let user_balance = read_u64(data, 48);
    env.effect(
        "total_supply wrapped around instead of failing",
        total_supply < 2 || total_supply == u64::MAX,
    );
    env.effect(
        "user_balance wrapped around instead of failing",
        user_balance < 1 || user_balance == u64::MAX,
    );
}"
}

